mapper.select:
SELECT '生产入库' AS flow_type, 'IN' AS direction, p.inbound_no AS bill_no, COALESCE(NULLIF(w.erp_stock_code, ''), w.warehouse_code) AS warehouse_code, COALESCE(NULLIF(m.kingdee_code, ''), m.material_code) AS material_code, m.material_name AS material_name, COALESCE(p.batch_no, '') AS batch_no, p.good_qty AS qty, p.update_time AS biz_time FROM wms_production_inbound p JOIN wms_location l ON l.id = p.location_id JOIN wms_warehouse w ON w.id = l.warehouse_id JOIN wms_material m ON m.id = p.material_id WHERE p.status = '已入库'
AND p.good_qty > 0 AND p.update_time BETWEEN #{windowStart} AND #{windowEnd} UNION ALL SELECT '生产入库' AS flow_type, 'IN' AS direction, p.inbound_no AS bill_no, COALESCE(NULLIF(sw.erp_stock_code, ''), sw.warehouse_code, '') AS warehouse_code, COALESCE(NULLIF(m.kingdee_code, ''), m.material_code) AS material_code, m.material_name AS material_name, COALESCE(p.batch_no, '') AS batch_no, p.bad_qty AS qty, p.update_time AS biz_time FROM wms_production_inbound p LEFT JOIN wms_location sl ON sl.id = p.scrap_location_id LEFT JOIN wms_warehouse sw ON sw.id = sl.warehouse_id JOIN wms_material m ON m.id = p.material_id WHERE p.status = '已入库'
AND p.bad_qty > 0 AND p.update_time BETWEEN #{windowStart} AND #{windowEnd}

SELECT '调拨' AS flow_type, 'OUT' AS direction, t.transfer_no AS bill_no, COALESCE(NULLIF(wout.erp_stock_code, ''), wout.warehouse_code) AS warehouse_code, COALESCE(NULLIF(m.kingdee_code, ''), m.material_code) AS material_code, m.material_name AS material_name, COALESCE(d.batch_no, '') AS batch_no, d.actual_qty AS qty, t.update_time AS biz_time FROM wms_transfer_order t JOIN wms_transfer_detail d ON d.transfer_id = t.id JOIN wms_warehouse wout ON wout.warehouse_code = t.out_warehouse_code AND wout.deleted_at = 0 JOIN wms_material m ON m.id = d.material_id WHERE t.status IN ('已完成', '已调整')
AND t.update_time BETWEEN #{windowStart} AND #{windowEnd} UNION ALL SELECT '调拨' AS flow_type, 'IN' AS direction, t.transfer_no AS bill_no, COALESCE(NULLIF(win.erp_stock_code, ''), win.warehouse_code) AS warehouse_code, COALESCE(NULLIF(m.kingdee_code, ''), m.material_code) AS material_code, m.material_name AS material_name, COALESCE(d.batch_no, '') AS batch_no, d.actual_qty AS qty, t.update_time AS biz_time FROM wms_transfer_order t JOIN wms_transfer_detail d ON d.transfer_id = t.id JOIN wms_warehouse win ON win.warehouse_code = t.in_warehouse_code AND win.deleted_at = 0 JOIN wms_material m ON m.id = d.material_id WHERE t.status IN ('已完成', '已调整')
AND t.update_time BETWEEN #{windowStart} AND #{windowEnd}

SELECT '盘点' AS flow_type, 'IN' AS direction, o.stocktake_no AS bill_no, COALESCE(NULLIF(w.erp_stock_code, ''), w.warehouse_code) AS warehouse_code, COALESCE(NULLIF(m.kingdee_code, ''), m.material_code) AS material_code, m.material_name AS material_name, COALESCE(d.batch_no, '') AS batch_no, ABS(d.diff_qty) AS qty, o.adjust_time AS biz_time FROM wms_stocktake_order o JOIN wms_stocktake_detail d ON d.stocktake_id = o.id JOIN wms_location l ON l.id = d.location_id JOIN wms_warehouse w ON w.id = l.warehouse_id JOIN wms_material m ON m.id = d.material_id WHERE o.status = '已调整'
AND d.diff_qty > 0 AND o.adjust_time BETWEEN #{windowStart} AND #{windowEnd} UNION ALL SELECT '盘点' AS flow_type, 'OUT' AS direction, o.stocktake_no AS bill_no, COALESCE(NULLIF(w.erp_stock_code, ''), w.warehouse_code) AS warehouse_code, COALESCE(NULLIF(m.kingdee_code, ''), m.material_code) AS material_code, m.material_name AS material_name, COALESCE(d.batch_no, '') AS batch_no, ABS(d.diff_qty) AS qty, o.adjust_time AS biz_time FROM wms_stocktake_order o JOIN wms_stocktake_detail d ON d.stocktake_id = o.id JOIN wms_location l ON l.id = d.location_id JOIN wms_warehouse w ON w.id = l.warehouse_id JOIN wms_material m ON m.id = d.material_id WHERE o.status = '已调整'
AND d.diff_qty < 0 AND o.adjust_time BETWEEN #{windowStart} AND #{windowEnd}
